import type { ReviewState } from '../../engine/contracts.js';
import { serializeGroupGenerationForReview } from '../../engine/review/groupCandidateSerialization.js';
import { buildJevPersonaEvidence, buildJevRecentHistoryText, buildReviewState } from '../../engine/review/reviewState.js';
import type { Persona, WardrobeState } from '../../managers.js';
import type { ChatRoom, RoomSceneState } from '../../roomManager.js';
import type { StrictReviewIssueCode } from '../../strictReview.js';
import type { JevSyntheticCalibrationCase, JevSyntheticExpected } from './jevSyntheticCalibration.js';

export type IsolationDimension = 'candidateText' | 'personaEvidence' | 'recentHistoryText' | 'participants' | 'sceneSummary' | 'proposedScene' | 'wardrobe' | 'ccMode' | 'mode' | 'realityLayer';
export type JevFactorFamily = 'group_narration' | 'persona_voice' | 'replayed_beat' | 'continuity' | 'wardrobe';
export type IsolationVariant = 'baseline' | 'variant' | 'positive-control' | 'anchor' | 'composite-control';
export interface JevFactorIsolationCase extends JevSyntheticCalibrationCase {
    suite: 'factor-isolation'; factorFamily: JevFactorFamily; factor: string; variant: IsolationVariant; baselineId?: string;
    changedDimensions: readonly IsolationDimension[]; mode: 'single' | 'group'; ccMode: boolean; shapeNotes: string; semanticCandidate: string;
}

const wardrobe: WardrobeState = { user: 'grey sweater', characters: { aster: 'green coat', beryl: 'blue scarf', cato: 'brown vest' } };
const aster: Persona = { name: 'Aster Vale', emoji: 'A', gender: 'female', description: 'A careful cartographer who notices practical details.', prompt: 'Speak in measured formal English. Never use slang. Keep the scene grounded.', greeting: '', avatarPrompt: '', avatarUrl: null };
const beryl: Persona = { name: 'Beryl Quill', emoji: 'B', gender: 'female', description: 'A warm singer who notices people before objects.', prompt: 'Speak in measured formal English. Never use slang. Keep the scene grounded.', greeting: '', avatarPrompt: '', avatarUrl: null };
const cato: Persona = { name: 'Cato Fern', emoji: 'C', gender: 'male', description: 'A reserved stagehand who tracks props and exits.', prompt: 'Speak in measured formal English. Never use slang. Keep the scene grounded.', greeting: '', avatarPrompt: '', avatarUrl: null };
const ccCelia: Persona = { ...aster, name: 'Celia North', description: 'A bilingual editor who weighs words before answering.', prompt: 'Use calm Traditional Chinese or formal English. Natural code-switching is allowed. Do not use slang.' };
const latest = 'Please describe the next careful step.';
const scene = (summary = 'Aster, Beryl, and Cato remain in the Lantern workshop beside a blue lantern.', unresolved = ['The north window remains closed.']): RoomSceneState => ({ id: 'isolation-scene', location: 'Lantern workshop', realityLayer: 'physical', realityEpochId: 'isolation-physical', presentMemberIds: ['aster', 'beryl', 'cato'], summary, unresolved, startedAt: 1, wardrobe });
const groupRoom = (): ChatRoom => ({ id: 'fictional-isolation-room', type: 'group', title: 'Lantern workshop', description: 'Fictional calibration room', leadMemberId: 'aster', members: [{ id: 'aster', persona: aster, joinedAt: 1, soul: [], memories: [] }, { id: 'beryl', persona: beryl, joinedAt: 1, soul: [], memories: [] }, { id: 'cato', persona: cato, joinedAt: 1, soul: [], memories: [] }], scene: scene(), sharedSoul: [], sharedMemories: [], createdAt: 1, updatedAt: 1, lastSummarizedUserMessageCount: 0 });
const history = (entries: readonly string[]) => buildJevRecentHistoryText([...entries.map((content, index) => ({ role: index % 2 ? 'assistant' : 'user', content })), { role: 'user', content: latest }], latest);
const normal = (candidateText: string, overrides: Partial<{ persona: Persona; ccMode: boolean; room: ChatRoom; history: string; proposedScene: RoomSceneState; wardrobe: WardrobeState }> = {}): ReviewState => buildReviewState({ mode: overrides.room ? 'group' : 'single', ccMode: overrides.ccMode ?? false, latestUserText: latest, candidateText, personaKey: 'aster', persona: overrides.persona ?? aster, room: overrides.room, wardrobe: overrides.wardrobe ?? wardrobe, recentHistoryText: overrides.history ?? history(['Please inspect the lantern.', 'Aster examines the blue lantern.']), proposedScene: overrides.proposedScene });
const replace = <K extends keyof ReviewState>(state: ReviewState, key: K, value: ReviewState[K]): ReviewState => ({ ...state, [key]: value });
const fullEnvelope = (chat: string): string => serializeGroupGenerationForReview({ text: chat, segments: [{ type: 'narration', text: chat }], scene: scene() });
export const diffIsolationReviewState = (baseline: ReviewState, variant: ReviewState): IsolationDimension[] => {
    const dimensions: readonly IsolationDimension[] = ['candidateText', 'personaEvidence', 'recentHistoryText', 'participants', 'sceneSummary', 'proposedScene', 'wardrobe', 'ccMode', 'mode', 'realityLayer'];
    return dimensions.filter(dimension => JSON.stringify(baseline[dimension]) !== JSON.stringify(variant[dimension]));
};
const cases: JevFactorIsolationCase[] = [];
const add = (id: string, family: JevFactorFamily, factor: string, variant: IsolationVariant, category: StrictReviewIssueCode, expected: JevSyntheticExpected, state: ReviewState, semanticCandidate: string, shapeNotes: string, changedDimensions: readonly IsolationDimension[] = [], baselineId?: string) => cases.push({ id, suite: 'factor-isolation', factorFamily: family, factor, variant, baselineId, changedDimensions, mode: state.mode, ccMode: state.ccMode, category, expected, description: `Fictional ${family} ${factor} ${variant}.`, state, semanticCandidate, shapeNotes });

// A. Group narration: candidate-only variants share one identical group state.
const groupSemantic = 'Aster checks the blue lantern while Beryl watches.';
const groupState = replace(normal(groupSemantic, { room: groupRoom() }), 'personaEvidence', buildJevPersonaEvidence(aster));
add('isolation-group-baseline', 'group_narration', 'plain-group-prose', 'baseline', 'group_narration', 'negative', groupState, groupSemantic, 'common group state');
add('isolation-group-chat-wrapper', 'group_narration', 'chat-wrapper', 'variant', 'group_narration', 'negative', replace(groupState, 'candidateText', `<chat>${groupSemantic}</chat>`), groupSemantic, 'chat tag only', ['candidateText'], 'isolation-group-baseline');
add('isolation-group-scene-tag', 'group_narration', 'scene-tag', 'variant', 'group_narration', 'negative', replace(groupState, 'candidateText', `${groupSemantic}<scene>{"location":"Lantern workshop"}</scene>`), groupSemantic, 'scene tag only', ['candidateText'], 'isolation-group-baseline');
add('isolation-group-npc-tag', 'group_narration', 'npc-candidate-tag', 'variant', 'group_narration', 'negative', replace(groupState, 'candidateText', `${groupSemantic}<npc_candidate>null</npc_candidate>`), groupSemantic, 'NPC tag only', ['candidateText'], 'isolation-group-baseline');
const labelledBaseline = replace(groupState, 'candidateText', 'Aster Vale: "Aster checks the blue lantern."\nBeryl Quill: "Beryl watches."');
add('isolation-group-labelled-dialogue', 'group_narration', 'labelled-dialogue', 'variant', 'group_narration', 'negative', labelledBaseline, groupSemantic, 'labelled dialogue only', ['candidateText'], 'isolation-group-baseline');
add('isolation-group-first-person-labelled', 'group_narration', 'first-person-inside-label', 'variant', 'group_narration', 'negative', replace(labelledBaseline, 'candidateText', 'Aster Vale: "I check the blue lantern."\nBeryl Quill: "I watch."'), groupSemantic, 'first person stays within labels', ['candidateText'], 'isolation-group-labelled-dialogue');
add('isolation-group-multi-persona', 'group_narration', 'multi-persona-evidence', 'variant', 'group_narration', 'negative', replace(groupState, 'personaEvidence', buildJevPersonaEvidence(aster, groupRoom())), groupSemantic, 'only persona evidence expands', ['personaEvidence'], 'isolation-group-baseline');
add('isolation-group-role-history', 'group_narration', 'role-labelled-complex-history', 'variant', 'group_narration', 'negative', replace(groupState, 'recentHistoryText', history(['Aster checks the lamp casing.', 'Beryl watches the north window.', 'Cato counts the tools.', 'Nobody leaves the Lantern workshop.'])), groupSemantic, 'recent history only', ['recentHistoryText'], 'isolation-group-baseline');
add('isolation-group-scene-duplication', 'group_narration', 'proposed-scene-duplication', 'variant', 'group_narration', 'negative', replace(replace(groupState, 'candidateText', `${groupSemantic}<scene>{"location":"Lantern workshop"}</scene>`), 'proposedScene', scene()), groupSemantic, 'only proposed scene is added to the scene-tag baseline', ['proposedScene'], 'isolation-group-scene-tag');
add('isolation-group-full-envelope', 'group_narration', 'full-production-envelope', 'composite-control', 'group_narration', 'negative', normal(fullEnvelope(groupSemantic), { room: groupRoom(), proposedScene: scene() }), groupSemantic, 'production-shaped composite anchor', ['candidateText', 'proposedScene']);
add('isolation-group-positive', 'group_narration', 'unlabelled-first-person', 'positive-control', 'group_narration', 'positive', replace(groupState, 'candidateText', 'I check the blue lantern while Beryl watches.'), 'I check the blue lantern while Beryl watches.', 'clear positive', ['candidateText']);

// B. Persona voice: each context has a matching baseline.
const normalVoice = 'Aster says, "The blue lantern is ready for inspection."';
const normalVoiceBase = normal(normalVoice);
add('isolation-persona-normal-baseline', 'persona_voice', 'normal-persona-context', 'baseline', 'persona_voice', 'negative', normalVoiceBase, normalVoice, 'normal single baseline');
for (const [id, persona, note] of [['long-description', { ...aster, description: `${aster.description} She records measurements, checks glass, and names each observed detail before conclusions.` }, 'description only'], ['long-prompt', { ...aster, prompt: `${aster.prompt} Use complete sentences. Refer to objects precisely. Avoid exclamation marks.` }, 'prompt only'], ['multiple-style-rules', { ...aster, prompt: 'Speak in measured formal English. Never use slang. Use complete sentences. Avoid exclamation marks. Refer to objects precisely.' }, 'rules only'], ['bilingual-evidence', { ...aster, description: `${aster.description} 她做事細心。`, prompt: 'Speak in measured formal English. Never use slang. 語氣冷靜。' }, 'language evidence only']] as const) add(`isolation-persona-${id}`, 'persona_voice', id, 'variant', 'persona_voice', 'negative', replace(normalVoiceBase, 'personaEvidence', buildJevPersonaEvidence(persona)), normalVoice, note, ['personaEvidence'], 'isolation-persona-normal-baseline');
const ccVoice = 'Celia 說：「藍色提燈已準備好檢查。」';
const ccVoiceBase = normal(ccVoice, { persona: ccCelia, ccMode: true });
add('isolation-persona-cc-baseline', 'persona_voice', 'cc-persona-context', 'baseline', 'persona_voice', 'negative', ccVoiceBase, 'Celia reports the lantern is ready.', 'Cc baseline permits both languages');
add('isolation-persona-cantonese-rule', 'persona_voice', 'cc-rule-language', 'variant', 'persona_voice', 'negative', replace(ccVoiceBase, 'personaEvidence', buildJevPersonaEvidence({ ...ccCelia, prompt: '用平靜的繁體中文或正式英文回答。自然中英夾雜可以。不可用俚語。' })), 'Celia reports the lantern is ready.', 'only Cc rule wording changes', ['personaEvidence'], 'isolation-persona-cc-baseline');
add('isolation-persona-cc-bilingual-evidence', 'persona_voice', 'cc-bilingual-evidence', 'variant', 'persona_voice', 'negative', replace(ccVoiceBase, 'personaEvidence', buildJevPersonaEvidence({ ...ccCelia, description: 'A bilingual editor. 她說話前會先衡量用字。' })), 'Celia reports the lantern is ready.', 'only Cc persona evidence changes', ['personaEvidence'], 'isolation-persona-cc-baseline');
add('isolation-persona-traditional-chinese-candidate', 'persona_voice', 'traditional-chinese-candidate', 'variant', 'persona_voice', 'negative', replace(ccVoiceBase, 'candidateText', 'Celia says, "The blue lantern is ready for inspection."'), 'Celia reports the lantern is ready.', 'same identity and event; candidate language only', ['candidateText'], 'isolation-persona-cc-baseline');
add('isolation-persona-code-switch-candidate', 'persona_voice', 'code-switch-candidate', 'variant', 'persona_voice', 'negative', replace(ccVoiceBase, 'candidateText', 'Celia 說：「藍色提燈已準備好，we can inspect it now。」'), 'Celia reports the lantern is ready.', 'permitted code switch only', ['candidateText'], 'isolation-persona-cc-baseline');
const groupVoice = replace(normal(normalVoice, { room: groupRoom() }), 'personaEvidence', buildJevPersonaEvidence(aster));
add('isolation-persona-group-baseline', 'persona_voice', 'group-persona-context', 'baseline', 'persona_voice', 'negative', groupVoice, normalVoice, 'group single evidence baseline');
const neutralEvidence = buildJevPersonaEvidence(aster, groupRoom());
add('isolation-persona-group-multi-persona', 'persona_voice', 'multi-persona-evidence', 'variant', 'persona_voice', 'negative', replace(groupVoice, 'personaEvidence', neutralEvidence), normalVoice, 'only persona evidence changes', ['personaEvidence'], 'isolation-persona-group-baseline');
const distinctRoom = groupRoom(); distinctRoom.members[1].persona = { ...beryl, prompt: 'Use warm direct dialogue.' }; distinctRoom.members[2].persona = { ...cato, prompt: 'Speak sparingly and describe observed facts.' };
add('isolation-persona-group-distinct-rules', 'persona_voice', 'distinct-group-rules', 'variant', 'persona_voice', 'negative', replace(replace(groupVoice, 'personaEvidence', neutralEvidence), 'personaEvidence', buildJevPersonaEvidence(aster, distinctRoom)), normalVoice, 'only member rules change', ['personaEvidence'], 'isolation-persona-group-multi-persona');
add('isolation-persona-positive-normal', 'persona_voice', 'normal-slang-violation', 'positive-control', 'persona_voice', 'positive', replace(normalVoiceBase, 'candidateText', 'Aster says, "Yo, this lantern is awesome."'), 'Aster says slang.', 'clear positive', ['candidateText']);
add('isolation-persona-positive-cc', 'persona_voice', 'cc-slang-violation', 'positive-control', 'persona_voice', 'positive', replace(ccVoiceBase, 'candidateText', 'Celia says, "Yo, 呢盞燈超 wild。"'), 'Celia says slang.', 'clear positive', ['candidateText']);
add('isolation-persona-positive-group', 'persona_voice', 'group-slang-violation', 'positive-control', 'persona_voice', 'positive', replace(groupVoice, 'candidateText', 'Aster says, "Yo, this lantern is awesome."'), 'Aster says slang.', 'clear positive', ['candidateText']);

// C. Replay variants are history-only, except declared scene duplication and composite anchor.
const replayCandidate = 'Aster repairs the blue lantern.';
const replayBase = normal(replayCandidate, { history: history(['Aster examines the damaged blue lantern but does not repair it.']) });
add('isolation-replay-baseline', 'replayed_beat', 'minimal-uncompleted-history', 'baseline', 'replayed_beat', 'negative', replayBase, replayCandidate, 'repair remains uncompleted');
for (const [factor, entries] of [['additional-role-labelled-turn', ['Please inspect the lantern.', 'Aster examines the damaged blue lantern but does not repair it.']], ['four-message-history', ['Please inspect the lantern.', 'Aster examines it but does not repair it.', 'Beryl checks the window.', 'Cato counts the tools.']], ['repeated-object-nouns', ['The blue lantern is on the bench.', 'Aster measures the blue lantern but does not repair the blue lantern.']], ['repeated-action-verb', ['Aster plans to repair the blue lantern later.', 'Aster does not repair the blue lantern yet.']], ['explicit-not-completed', ['Aster did not complete the repair of the blue lantern.']], ['different-object', ['Aster repairs a brass lantern but does not repair the blue lantern.']], ['different-participant', ['Beryl repairs a paper lantern; Aster does not repair the blue lantern.']]] as const) add(`isolation-replay-${factor}`, 'replayed_beat', factor, 'variant', 'replayed_beat', 'negative', replace(replayBase, 'recentHistoryText', history(entries)), replayCandidate, 'history only; target remains uncompleted', ['recentHistoryText'], 'isolation-replay-baseline');
const replaySceneBase = replace(replayBase, 'candidateText', `${replayCandidate}<scene>{"location":"Lantern workshop"}</scene>`);
add('isolation-replay-scene-duplication', 'replayed_beat', 'proposed-scene-duplication', 'variant', 'replayed_beat', 'negative', replace(replaySceneBase, 'proposedScene', scene('The blue lantern remains damaged in the Lantern workshop.')), replayCandidate, 'proposed scene only', ['proposedScene'], 'isolation-replay-candidate-scene-tag');
add('isolation-replay-scene-summary', 'replayed_beat', 'scene-summary-object', 'variant', 'replayed_beat', 'negative', replace(replayBase, 'sceneSummary', 'The damaged blue lantern remains on the workbench.'), replayCandidate, 'scene summary only; repair remains uncompleted', ['sceneSummary'], 'isolation-replay-baseline');
add('isolation-replay-candidate-scene-tag', 'replayed_beat', 'candidate-scene-tag', 'variant', 'replayed_beat', 'negative', replace(replayBase, 'candidateText', `${replayCandidate}<scene>{"location":"Lantern workshop"}</scene>`), replayCandidate, 'candidate transport tag only; repair remains uncompleted', ['candidateText'], 'isolation-replay-baseline');
add('isolation-replay-full-envelope', 'replayed_beat', 'full-group-envelope', 'composite-control', 'replayed_beat', 'negative', normal(fullEnvelope(replayCandidate), { room: groupRoom(), proposedScene: scene(), history: history(['Aster examines the blue lantern but does not repair it.']) }), replayCandidate, 'production-shaped composite anchor', ['candidateText', 'personaEvidence', 'participants', 'sceneSummary', 'proposedScene', 'mode']);
add('isolation-replay-positive', 'replayed_beat', 'completed-beat', 'positive-control', 'replayed_beat', 'positive', normal('Aster repairs the blue lantern again from the beginning.', { history: history(['Aster repaired the blue lantern completely and placed it on the workbench.']) }), 'Aster repeats a completed repair.', 'clear positive');

// D. Continuity uses context-matched structural baselines.
const continuityCandidate = 'Aster remains in the Lantern workshop and checks the blue lantern.';
const continuityBase = normal(continuityCandidate, { history: history(['Aster is in the Lantern workshop.']) });
add('isolation-continuity-baseline', 'continuity', 'minimal-history', 'baseline', 'continuity', 'negative', continuityBase, continuityCandidate, 'minimal location-consistent state');
add('isolation-continuity-four-history', 'continuity', 'four-role-history', 'variant', 'continuity', 'negative', replace(continuityBase, 'recentHistoryText', history(['Aster is in the Lantern workshop.', 'Beryl watches the north window.', 'Cato counts the tools.', 'Everyone remains in the Lantern workshop.'])), continuityCandidate, 'history only', ['recentHistoryText'], 'isolation-continuity-baseline');
add('isolation-continuity-repeated-location', 'continuity', 'repeated-location', 'variant', 'continuity', 'negative', replace(continuityBase, 'recentHistoryText', history(['The Lantern workshop is quiet.', 'Aster remains in the Lantern workshop beside the blue lantern.'])), continuityCandidate, 'history only', ['recentHistoryText'], 'isolation-continuity-baseline');
add('isolation-continuity-participants', 'continuity', 'several-participants', 'variant', 'continuity', 'negative', replace(continuityBase, 'participants', [...continuityBase.participants, { id: 'beryl', name: 'Beryl Quill', present: true, role: 'active character' }]), continuityCandidate, 'participants only', ['participants'], 'isolation-continuity-baseline');
add('isolation-continuity-scene-summary', 'continuity', 'scene-summary', 'variant', 'continuity', 'negative', replace(continuityBase, 'sceneSummary', 'Aster remains in the Lantern workshop beside the blue lantern.'), continuityCandidate, 'scene summary only', ['sceneSummary'], 'isolation-continuity-baseline');
const unresolvedBase = replace(continuityBase, 'proposedScene', scene('Aster remains in the Lantern workshop.', []));
add('isolation-continuity-unresolved-baseline', 'continuity', 'empty-unresolved-scene', 'baseline', 'continuity', 'negative', unresolvedBase, continuityCandidate, 'empty unresolved scene');
add('isolation-continuity-unresolved', 'continuity', 'unresolved-item', 'variant', 'continuity', 'negative', replace(unresolvedBase, 'proposedScene', scene('Aster remains in the Lantern workshop.', ['The north window remains closed.'])), continuityCandidate, 'proposed scene unresolved item only', ['proposedScene'], 'isolation-continuity-unresolved-baseline');
add('isolation-continuity-proposed-scene', 'continuity', 'proposed-scene', 'variant', 'continuity', 'negative', replace(continuityBase, 'proposedScene', scene('Aster remains in the Lantern workshop beside the blue lantern.')), continuityCandidate, 'proposed scene only', ['proposedScene'], 'isolation-continuity-baseline');
add('isolation-continuity-embedded-scene', 'continuity', 'embedded-scene', 'variant', 'continuity', 'negative', replace(continuityBase, 'candidateText', `${continuityCandidate}<scene>{"location":"Lantern workshop"}</scene>`), continuityCandidate, 'candidate text only', ['candidateText'], 'isolation-continuity-baseline');
const continuitySceneBase = replace(continuityBase, 'candidateText', `${continuityCandidate}<scene>{"location":"Lantern workshop"}</scene>`);
add('isolation-continuity-scene-duplication', 'continuity', 'proposed-scene-duplication', 'variant', 'continuity', 'negative', replace(continuitySceneBase, 'proposedScene', scene('Aster remains in the Lantern workshop beside the blue lantern.')), continuityCandidate, 'matching proposed scene only', ['proposedScene'], 'isolation-continuity-embedded-scene');
add('isolation-continuity-full-envelope', 'continuity', 'full-group-envelope', 'composite-control', 'continuity', 'negative', normal(fullEnvelope(continuityCandidate), { room: groupRoom(), proposedScene: scene(), history: history(['Aster remains in the Lantern workshop.']) }), continuityCandidate, 'production-shaped composite anchor', ['candidateText', 'personaEvidence', 'participants', 'sceneSummary', 'proposedScene', 'mode']);
add('isolation-continuity-positive', 'continuity', 'obvious-location-contradiction', 'positive-control', 'continuity', 'positive', replace(continuityBase, 'candidateText', 'Without leaving, Aster is suddenly at a mountain summit.'), 'Aster is suddenly at a mountain summit.', 'clear positive', ['candidateText']);

add('isolation-wardrobe-conflict', 'wardrobe', 'established-outfit-conflict', 'anchor', 'wardrobe', 'positive', normal('Aster smooths the red coat she is wearing.'), 'Aster wears a red coat.', 'green coat is established');
add('isolation-wardrobe-unspecified', 'wardrobe', 'unestablished-outfit', 'anchor', 'wardrobe', 'negative', normal('Aster adjusts a red scarf.', { wardrobe: { user: 'grey sweater', characters: {} } }), 'Aster adjusts a red scarf.', 'no Aster outfit is supplied');
export const JEV_FACTOR_ISOLATION_CASES: readonly JevFactorIsolationCase[] = cases;
export const FACTOR_ISOLATION_HELPERS = ['buildReviewState', 'buildJevPersonaEvidence', 'buildJevRecentHistoryText', 'serializeGroupGenerationForReview'] as const;
